  /* ---------------- markdown rendering ---------------- */
  function escS(s){ return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
  function hlCode(code, lang){
    let h = escS(code);
    h = h.replace(/(\/\/.*$|\/\*[\s\S]*?\*\/|#[^\n]*)/gm, m => '<span class="md-c">'+m+'</span>');
    h = h.replace(/("(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*')/g, m => '<span class="md-s">'+m+'</span>');
    h = h.replace(new RegExp('\\b(function|return|if|else|for|while|do|switch|case|break|continue|const|let|var|import|export|from|class|new|typeof|void|try|catch|throw|async|await|def|print|int|float|double|char|include|define|struct|void|printf|scanf|True|False|None|and|or|not|in|is|lambda)\\b','g'), m => '<span class="md-k">'+m+'</span>');
    h = h.replace(/\b(\d+(\.\d+)?)\b/g, m => '<span class="md-n">'+m+'</span>');
    return '<pre class="md-pre"><div class="md-lang">'+escS(lang||'code')+'</div><code class="md-code">'+h+'</code></pre>';
  }
  function inlineMD(s){
    s = escS(s);
    s = s.replace(/`([^`]+)`/g, '<code class="md-ic">$1</code>');
    s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    s = s.replace(/__([^_]+)__/g, '<strong>$1</strong>');
    s = s.replace(/(^|[^*])\*([^*\n]+)\*/g, '$1<em>$2</em>');
    s = s.replace(/(^|[^_])_([^_\n]+)_/g, '$1<em>$2</em>');
    s = s.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
    s = s.replace(/~~([^~]+)~~/g, '<del>$1</del>');
    return s;
  }
  function mdRender(md){
    if(!md) return '';
    let lines = md.replace(/\r\n?/g,'\n').split('\n');
    let html = '', i = 0, list = null;
    while(i < lines.length){
      const line = lines[i];
      const cb = line.match(/^```([\w-]*)\s*$/);
      if(cb){
        const lang = cb[1], buf = [];
        i++;
        while(i < lines.length && !/^```\s*$/.test(lines[i])){ buf.push(lines[i]); i++; }
        i++; // skip ```
        html += hlCode(buf.join('\n'), lang); list = null; continue;
      }
      const hh = line.match(/^(#{1,6})\s+(.*)$/);
      if(hh){ const lv = hh[1].length; html += '<h'+lv+' class="md-h">'+inlineMD(hh[2])+'</h'+lv+'>'; list = null; i++; continue; }
      if(/^\s*[-*_]{3,}\s*$/.test(line)){ html += '<hr class="md-hr">'; list = null; i++; continue; }
      if(line.indexOf('>') === 0){
        const bb = [];
        while(i < lines.length && lines[i].indexOf('>') === 0){ bb.push(lines[i].replace(/^>\s?/,'')); i++; }
        html += '<blockquote class="md-bq">'+inlineMD(bb.join('<br>'))+'</blockquote>'; list = null; continue;
      }
      if(/^\s*[-*+]\s+/.test(line)){
        if(list !== 'ul'){ if(list) html += '</li></ul>'; html += '<ul class="md-ul">'; list = 'ul'; }
        html += '<li>'+inlineMD(line.replace(/^\s*[-*+]\s+/,''))+'</li>'; i++; continue;
      }
      if(/^\s*\d+\.\s+/.test(line)){
        if(list !== 'ol'){ if(list) html += '</li></ol>'; html += '<ol class="md-ol">'; list = 'ol'; }
        html += '<li>'+inlineMD(line.replace(/^\s*\d+\.\s+/,''))+'</li>'; i++; continue;
      }
      if(list){ html += '</li></' + (list === 'ul' ? 'ul' : 'ol') + '>'; list = null; }
      if(line.trim() === ''){ i++; continue; }
      html += '<p class="md-p">'+inlineMD(line)+'</p>'; i++;
    }
    if(list){ html += '</li></' + (list === 'ul' ? 'ul' : 'ol') + '>'; }
    return html;
  }

  /* ---------------- rendering ---------------- */
  let typingFull = "";
  function stopTyping() {
    if (typing) { clearInterval(typing); typing = null; }
  }
  function showInstant(text, html) {
    stopTyping();
    if (html) textEl.innerHTML = '<div class="ds-markdown">' + html + '</div>';
    else textEl.innerHTML = mdRender(text);
  }
